    input.push_str("#if FEATURE\n  if(run){\n    run();\n  }else\n#endif\n\n  if(show){\n    switch(state){\n      case 0:  z = \"off\"; break;\n      default: z = \"on\"; break;\n      case 2:  z = \"two\"; break;\n    }\n  }\n}\n");
