#[test]
fn else_if_body_after_switch_in_split_else_keeps_branch_indent() {
    check(
        r#"void f(int value){
#if FEATURE
  if( a0 ){ call0(); }else
#endif

  if( a1 ){ call1(); }else

  if( a2 ){ call2(); }else

#if FEATURE
  if( a3 ){ call3(); }else
#endif

  if( b ){
    int ok = 0;
    switch(value){
      case ONE: {
        ok = 1;
        break;
      }
      case TWO: {
        int x;
        if( n>=3 ){
          x = value(arg);
          call(db, schema, code, &x);
        }
        ok = 2;
        break;
      }
    }
    if( ok==0 && index>=0 ){
      report(out, "Usage: %s %s\\n",
              name, items[index].usage);
      rc = 1;
    }else if( ok==1 ){
      char text[100];
      write(text, "%lld", result);
      report(out, "%s\\n", text);
    }
  }else

  if( c ){
    next();
  }
}
"#,
        &[],
        r#"void f(int value) {
#if FEATURE
    if( a0 ) {
        call0();
    } else
#endif

        if( a1 ) {
            call1();
        } else

            if( a2 ) {
                call2();
            } else

#if FEATURE
                if( a3 ) {
                    call3();
                } else
#endif

                    if( b ) {
                        int ok = 0;
                        switch(value) {
                        case ONE: {
                            ok = 1;
                            break;
                        }
                        case TWO: {
                            int x;
                            if( n>=3 ) {
                                x = value(arg);
                                call(db, schema, code, &x);
                            }
                            ok = 2;
                            break;
                        }
                        }
                        if( ok==0 && index>=0 ) {
                            report(out, "Usage: %s %s\\n",
                                   name, items[index].usage);
                            rc = 1;
                        } else if( ok==1 ) {
                            char text[100];
                            write(text, "%lld", result);
                            report(out, "%s\\n", text);
                        }
                    } else

                        if( c ) {
                            next();
                        }
}
"#,
    );
}

