    let expected = "void f()\n{\n    while (x)\n        {\n        for (i = 0; i < n; i++)\n            if (!w)\n                { break; }\n\n        y();\n        }\n    for (i = 0; i < n; i++)\n        if (!w)\n        { break; }\n    z();\n}\n";
