    let expected = "void f()\n{\n    value = 0;\nretry:\n\n    /* note */\n    for (;;) {\n        value = 1;\n    }\n\n    switch (state) {\nagain:\n\n    /* note */\n    case 1:\n        value = 1;\n        break;\n    }\n}\n";
