    check(
        input,
        &["--style=kr"],
        "void f()\n{\n    switch (state) {\n    case 1:\n#line 46 \"input.l\"\n#ifdef FEATURE\n        {\n#endif\n            pop(state);\n        }\n        break;\n    }\n}\n",
    );
