    let input = "void f()\n{\n    switch (k) {  /* a\n          b */ /* c */\n    case 1:\n        break;\n    }\n}\n";
    let expected = "void f()\n{\n    switch (k)\n    {\n    /* a\n          b */ /* c */\n    case 1:\n        break;\n    }\n}\n";
