    let expected = "void helper()\n{\n    check(value.size() >= 2\n          || value[1])\n        << describe(value);\n    stream << check(value.size() >= 2\n                    || value[1])\n           << describe(value);\n    VERIFY(value.size() >= 2\n           && value[1] == 0)\n        << describe(value);\n}\n";
